#define main base_search_main
#include "base-search.cpp"
#undef main
#include <chrono>
struct Part {State cells;double x=0,y=0,r=0,travel=0;};
vector<Part> parts(Graph&g,const State&s,double ix,double iy){map<int,int>left(s.begin(),s.end());vector<Part>out;while(!left.empty()){Part p;vector<int>q{left.begin()->first};p.cells.push_back(*left.begin());left.erase(left.begin());for(size_t h=0;h<q.size();h++){set<int>near;for(int v:g.adj[q[h]]){near.insert(v);for(int w:g.adj[v])near.insert(w);}for(int v:near){auto it=left.find(v);if(it!=left.end()){q.push_back(v);p.cells.push_back(*it);left.erase(it);}}}for(auto[c,v]:p.cells){p.x+=g.x[c];p.y+=g.y[c];}p.x/=p.cells.size();p.y/=p.cells.size();for(auto[c,v]:p.cells)p.r=max(p.r,hypot(g.x[c]-p.x,g.y[c]-p.y));p.travel=hypot(p.x-ix,p.y-iy);out.push_back(p);}return out;}
State connected(Graph&g,RNG&r,const vector<int>&starts,int size,int C,int mode){vector<int>cells{starts[r.n(starts.size())]};set<int>included(cells.begin(),cells.end());for(int k=0;int(cells.size())<size&&k<size*60;k++){int c=cells[r.n(cells.size())],v=g.adj[c][r.n(g.adj[c].size())];if(included.insert(v).second)cells.push_back(v);}State st;for(int c:cells)st.push_back({c,mode==0?1:(r.n(3)?1:1+r.n(C-1))});sort(st.begin(),st.end());return st;}
int main(int argc,char**argv){if(argc<7){cerr<<"graph prefix seed trials horizon mode\n";return 2;}Graph g(argv[1]);string prefix=argv[2],mode=argv[6];RNG random{stoull(argv[3])};int trials=stoi(argv[4]),H=stoi(argv[5]);Engine engine(g);vector<int>starts,high;for(int c=0;c<g.n;c++)if(g.bound[c]>=70&&hypot(g.x[c],g.y[c])<38){starts.push_back(c);if(g.adj[c].size()>=8)high.push_back(c);}if(starts.empty())throw runtime_error("no eligible starts");ofstream out(prefix+".jsonl"),acc(prefix+".account.json");map<string,double>best;map<string,uint64_t>outcomes,byConfig;uint64_t qualifying=0,emitters=0;auto began=chrono::steady_clock::now();for(int trial=0;trial<trials;trial++){int C=4+random.n(7);if(trial%16==0)C=3;int B=1<<2,S=0;int n=4+random.n(3),phase=trial%5==0;if(trial%8==0)n=7+random.n(18);if(mode=="high"){C=2+random.n(8);B|=1<<(8+random.n(4));if(random.n(2))S|=1<<(8+random.n(4));if(random.n(2))B|=1<<3;n=8+random.n(25);phase=random.n(2);}auto &pool=(mode=="high"&&!high.empty())?high:starts;State init=connected(g,random,pool,n,C,phase);double ix=0,iy=0;for(auto[c,v]:init){ix+=g.x[c];iy+=g.y[c];}ix/=init.size();iy/=init.size();Result r=engine.run(init,B,S,C,H,1800,210);outcomes[r.outcome]++;byConfig[rule(B,S)+"/"+to_string(C)+"/"+to_string(init.size())]++;if(r.outcome=="horizon"&&r.minBoundary>=5){auto pp=parts(g,r.final,ix,iy);int mobile=0,source=0;bool good=true;for(auto&p:pp){if(p.cells.size()>=4&&p.cells.size()<=45&&p.r<=6&&p.travel>45)mobile++;else if(p.travel<16&&p.r<14&&p.cells.size()<250)source++;else good=false;}if(good&&mobile>=2){qualifying++;if(source)emitters++;string key=to_string(C)+"/"+to_string(mobile)+"/"+to_string(source);double score=1000-init.size()*3-r.final.size()*0.4-r.maxRadius*0.001;if(!best.count(key)||score>best[key]){best[key]=score;emit(out,r,B,S,C,mobile,trial,argv[1]);out.flush();cerr<<"HIT trial="<<trial<<" C="<<C<<" mobile="<<mobile<<" source="<<source<<" seed="<<init.size()<<" active="<<r.final.size()<<" rule="<<rule(B,S)<<"\n";}}}if(trial%5000==4999)cerr<<"PROGRESS trials="<<trial+1<<" transitions="<<engine.totalSteps<<" qualifying="<<qualifying<<" sources="<<emitters<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-began).count()<<"\n";}
acc<<"{\"graph\":\""<<argv[1]<<"\",\"rng\":\"xorshift64star\",\"rngSeed\":\""<<argv[3]<<"\",\"mode\":\""<<mode<<"\",\"trials\":"<<trials<<",\"actualTransitions\":"<<engine.totalSteps<<",\"highBirthEvents\":"<<engine.highBirthEvents<<",\"highSurvivalEvents\":"<<engine.highSurvivalEvents<<",\"horizon\":"<<H<<",\"eligibleStarts\":"<<starts.size()<<",\"highDegreeStarts\":"<<high.size()<<",\"qualifyingExecutions\":"<<qualifying<<",\"sourceAndMobileExecutions\":"<<emitters<<",\"elapsedSeconds\":"<<chrono::duration<double>(chrono::steady_clock::now()-began).count()<<",\"outcomes\":{";bool first=true;for(auto&[k,v]:outcomes){if(!first)acc<<',';first=false;acc<<'\"'<<k<<"\":"<<v;}acc<<"},\"byConfigurationSeedSize\":{";first=true;for(auto&[k,v]:byConfig){if(!first)acc<<',';first=false;acc<<'\"'<<k<<"\":"<<v;}acc<<"}}\n";cerr<<"COMPLETE trials="<<trials<<" transitions="<<engine.totalSteps<<"\n";}
